fn saturation_above_safe_exponent_does_not_overflow() {
    let cfg = RetryConfig::new(5, 1u64 << 62, 1u64 << 63);
    let mut sleeper = FakeSleeper::default();
    let _ = run_job(&cfg, &mut sleeper, || Err(transient("always")));
    assert_eq!(
        sleeper.sleeps,
        vec![1u64 << 62, 1u64 << 63, 1u64 << 63, 1u64 << 63]
    );
}

