+        assert_eq!(cfg.delay_before_retry(0), 10);
+    }
+
+    #[test]
+    fn delay_doubles_exponentially() {
+        let cfg = RetryConfig::new(10, 10, 10_000);
+        assert_eq!(cfg.delay_before_retry(0), 10);
+        assert_eq!(cfg.delay_before_retry(1), 20);
+        assert_eq!(cfg.delay_before_retry(2), 40);
+        assert_eq!(cfg.delay_before_retry(3), 80);
+    }
+
+    #[test]
+    fn delay_saturates_at_max_delay() {
+        let cfg = RetryConfig::new(10, 10, 100);
+        assert_eq!(cfg.delay_before_retry(3), 80);
+        assert_eq!(cfg.delay_before_retry(4), 100);
+        assert_eq!(cfg.delay_before_retry(5), 100);
+        assert_eq!(cfg.delay_before_retry(100), 100);
+    }
+
+    #[test]
+    fn attempts_above_safe_exponent_saturate_without_overflow() {
+        // 2^63 is the largest power of two representable in u64.
+        let cfg = RetryConfig::new(100, 1, u64::MAX);
+        assert_eq!(cfg.delay_before_retry(62), 1u64 << 62);
+        assert_eq!(cfg.delay_before_retry(63), 1u64 << 63);
+        // 2^64 would overflow; the delay must saturate at max_delay_ms.
+        assert_eq!(cfg.delay_before_retry(64), u64::MAX);
